package handlers.skill.effects;

import org.l2jmobius.gameserver.entity.Location;
import org.l2jmobius.gameserver.entity.actor.Creature;
import org.l2jmobius.gameserver.entity.item.instance.Item;
import org.l2jmobius.gameserver.geoengine.GeoEngine;
import org.l2jmobius.gameserver.mechanics.effects.AbstractEffect;
import org.l2jmobius.gameserver.mechanics.skill.Skill;
import org.l2jmobius.gameserver.mechanics.skill.enums.FlyType;
import org.l2jmobius.gameserver.network.serverpackets.FlyToLocation;
import org.l2jmobius.gameserver.network.serverpackets.ValidateLocation;
import org.l2jmobius.gameserver.util.StatSet;

/**
 * This class handles the {@code FlyAway} skill effect.<br>
 * It implements the logic for the "Throw Up" mechanic to move a creature.<br>
 * It manages the transition of an entity to a new location.
 */
public class FlyAway extends AbstractEffect
{
	private final int _radius;
	
	/**
	 * Creates a new {@code FlyAway} effect.<br>
	 * This constructor initializes the effect using the provided statistics.
	 * @param params The {@code StatSet} containing the configuration values for this effect.
	 */
	public FlyAway(StatSet params)
	{
		_radius = params.getInt("radius");
	}
	
	/**
	 * Checks if the effect occurs immediately.<br>
	 * This method always returns {@code true}.
	 * @return {@code true} if the effect is instant.
	 */
	@Override
	public boolean isInstant()
	{
		return true;
	}
	
	/**
	 * Executes the instant effect of throwing a creature away.<br>
	 * It calculates a new position based on the distance between two creatures.<br>
	 * The target is moved to a valid location and updated in the world.
	 * @param effector The {@code Creature} performing the action.
	 * @param effected The {@code Creature} being pushed away.
	 * @param skill The {@code Skill} used to trigger this effect.
	 * @param item The {@code Item} associated with the skill execution.
	 */
	@Override
	public void instant(Creature effector, Creature effected, Skill skill, Item item)
	{
		// Anything a script pinned in place stays put.
		if (effected.isImmobilized())
		{
			return;
		}
		
		final int dx = effector.getX() - effected.getX();
		final int dy = effector.getY() - effected.getY();
		final double distance = Math.sqrt((dx * dx) + (dy * dy));
		final double nRadius = effector.getCollisionRadius() + effected.getCollisionRadius() + _radius;
		
		final int x = (int) (effector.getX() - (nRadius * (dx / distance)));
		final int y = (int) (effector.getY() - (nRadius * (dy / distance)));
		final int z = effector.getZ();
		
		final Location destination = GeoEngine.getInstance().getValidLocation(effected.getX(), effected.getY(), effected.getZ(), x, y, z, effected.getInstanceWorld());
		
		effected.broadcastPacket(new FlyToLocation(effected, destination, FlyType.THROW_UP));
		effected.setXYZ(destination);
		effected.broadcastPacket(new ValidateLocation(effected));
		effected.revalidateZone(true);
	}
}
